const phraseMap = new Map(phrases.map(([english, tamil, hindi, spanish]) => [english.toLocaleLowerCase(), { ta: tamil, hi: hindi, es: spanish }]));
const expression = new RegExp(phrases.map(([english]) => {
  const escaped = english.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const left = /^[a-z\d]/i.test(english) ? '(?<![a-z\d])' : '';
  const right = /[a-z\d]$/i.test(english) ? '(?![a-z\d])' : '';
  return { english, pattern: `${left}${escaped}${right}` };
}).sort((a, b) => b.english.length - a.english.length).map((item) => item.pattern).join('|'), 'gi');

export function readLanguage() {
  try { const value = localStorage.getItem(LANGUAGE_KEY); return languages.some((language) => language.code === value) ? value : 'en'; }
  catch { return 'en'; }
}

export function saveLanguage(value) {
  const language = languages.some((item) => item.code === value) ? value : 'en';
  try { localStorage.setItem(LANGUAGE_KEY, language); } catch { /* Language still applies for this session. */ }
  return language;
}

export function localeFor(language = readLanguage()) {
  return languages.find((item) => item.code === language)?.locale || 'en-IN';
}

export function speechLocaleFor(language = readLanguage()) {
  return languages.find((item) => item.code === language)?.speech || 'en-IN';
}

export function translateText(value, language = readLanguage()) {
  if (language === 'en' || !value) return value;
  return String(value).replace(expression, (match) => phraseMap.get(match.toLocaleLowerCase())?.[language] || match);
}

export function applyTranslations(container, language = readLanguage()) {
  document.documentElement.lang = language;
  document.title = translateText('GrandCare — Live long, live free', language);
  if (!container || language === 'en') return;
  for (const option of container.querySelectorAll('option:not([value])')) option.value = option.textContent;
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || parent.closest('script,style,textarea,pre,.message,.med-instructions,.instruction-box p,.prescription-file-copy strong')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) node.nodeValue = translateText(node.nodeValue, language);
  for (const element of container.querySelectorAll('[placeholder],[aria-label],[title],[alt]')) {
    for (const name of ['placeholder', 'aria-label', 'title', 'alt']) {
      if (element.hasAttribute(name)) element.setAttribute(name, translateText(element.getAttribute(name), language));
    }
  }
}
